param([Parameter(Mandatory=$true)][string]$BackupFile,[switch]$ConfirmLocalRestore)
$ErrorActionPreference="Stop";if(-not $ConfirmLocalRestore){throw "Refusing restore. Re-run with -ConfirmLocalRestore. This script only restores local D1."};$root=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path;$file=(Resolve-Path -LiteralPath $BackupFile).Path;if([IO.Path]::GetExtension($file)-ne ".sql"){throw "Backup must be a .sql file"};if((Get-Item $file).Length-lt 10){throw "Backup is empty"};Write-Host "Restoring into LOCAL D1 emulator only: $file";pnpm exec wrangler d1 execute krupim-mathlearning --local --file $file;if($LASTEXITCODE-ne 0){throw "Local restore failed"};Write-Host "Local restore completed. Run application smoke tests before any separately reviewed production recovery."
